import { extname, join } from "node:path";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import fs from "node:fs";
type GenericRecord = Record<string, unknown>;

type AssessmentPdfBuildInput = {
  analysis?: GenericRecord | null;
  summary?: GenericRecord | null;
  rows?: GenericRecord[] | null;
  schoolProfile?: GenericRecord | null;
};

type StudentSummary = {
  name: string;
  percentage: number;
  score: number | null;
  total: number | null;
};

type SubjectSummary = {
  name: string;
  averagePercentage: number;
  studentsCount: number;
};

type LevelSummary = {
  title: string;
  colorClass: "green" | "blue" | "turq" | "red";
  count: number;
  percentage: number;
  range: string;
};

function escapeHtml(value: unknown): string {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function asRecord(value: unknown): GenericRecord {
  return value && typeof value === "object" ? (value as GenericRecord) : {};
}

function asArray(value: unknown): unknown[] {
  return Array.isArray(value) ? value : [];
}

function asNumber(value: unknown): number | null {
  if (typeof value === "number" && Number.isFinite(value)) return value;

  if (typeof value === "string") {
    const normalized = value
      .replace(/[٪%]/g, "")
      .replace(/,/g, "")
      .replace(/،/g, "")
      .trim();

    const parsed = Number(normalized);
    return Number.isFinite(parsed) ? parsed : null;
  }

  return null;
}

function pickText(...values: unknown[]) {
  for (const value of values) {
    if (typeof value === "string" && value.trim()) return value.trim();
    if (typeof value === "number" && Number.isFinite(value)) return String(value);
  }

  return "";
}

function unique(items: string[]) {
  return Array.from(new Set(items.map((item) => item.trim()).filter(Boolean)));
}

function round(value: number, digits = 1) {
  const factor = 10 ** digits;
  return Math.round(value * factor) / factor;
}

function formatNumber(value: number | null | undefined, digits = 1, fallback = "غير متوفر") {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return round(value, digits).toLocaleString("en-US", {
    minimumFractionDigits: digits > 0 ? 0 : 0,
    maximumFractionDigits: digits,
  });
}

function formatPercent(value: number | null | undefined, digits = 1, fallback = "غير متوفر") {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return `${formatNumber(value, digits, fallback)}%`;
}

function formatDate(value: unknown) {
  const date = value ? new Date(String(value)) : new Date();

  if (Number.isNaN(date.getTime())) {
    return new Intl.DateTimeFormat("ar-EG-u-ca-gregory", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(new Date());
  }

  return new Intl.DateTimeFormat("ar-EG-u-ca-gregory", {
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(date);
}

function normalizeSubjectText(value: string) {
  const cleaned = value
    .replace(/القران/g, "القرآن")
    .replace(/الاسلاميه/g, "الإسلامية")
    .replace(/اسلاميه/g, "إسلامية")
    .replace(/اللغه/g, "اللغة")
    .replace(/العربيه/g, "العربية")
    .replace(/الانجليزيه/g, "الإنجليزية")
    .replace(/رقميه/g, "الرقمية")
    .replace(/البدنيه/g, "البدنية")
    .replace(/الفنيه/g, "الفنية")
    .replace(/الاسريه/g, "الأسرية");

  return cleaned.trim();
}

function getRowStudentName(row: GenericRecord) {
  return pickText(
    row.studentName,
    row.fullName,
    row.name,
    row.student,
    row["اسم الطالب"],
    row["اسم الطالبة"],
    row["الطالب"],
    row["الطالبة"]
  );
}

function getRowSubject(row: GenericRecord) {
  return normalizeSubjectText(
    pickText(row.subject, row.subjectName, row["المادة"], row["اسم المادة"], row.course)
  );
}

function getRowGrade(row: GenericRecord) {
  return pickText(row.grade, row.gradeName, row.stage, row["الصف"], row["المرحلة"]);
}

function getRowClassroom(row: GenericRecord) {
  return pickText(row.classroom, row.className, row.section, row["الفصل"], row["الشعبة"]);
}

function getRowScore(row: GenericRecord) {
  return (
    asNumber(row.score) ??
    asNumber(row.obtainedScore) ??
    asNumber(row.degree) ??
    asNumber(row.mark) ??
    asNumber(row["الدرجة"]) ??
    asNumber(row["درجة الطالب"]) ??
    null
  );
}

function getRowTotal(row: GenericRecord) {
  return (
    asNumber(row.totalScore) ??
    asNumber(row.maxScore) ??
    asNumber(row.total) ??
    asNumber(row.fullMark) ??
    asNumber(row["الدرجة الكلية"]) ??
    asNumber(row["النهاية العظمى"]) ??
    null
  );
}

function getRowPercentage(row: GenericRecord) {
  const direct =
    asNumber(row.percentage) ??
    asNumber(row.averagePercentage) ??
    asNumber(row.percent) ??
    asNumber(row["النسبة"]) ??
    asNumber(row["نسبة الإتقان"]);

  if (typeof direct === "number" && Number.isFinite(direct)) return direct;

  const score = getRowScore(row);
  const total = getRowTotal(row);

  if (
    typeof score === "number" &&
    Number.isFinite(score) &&
    typeof total === "number" &&
    Number.isFinite(total) &&
    total > 0
  ) {
    return (score / total) * 100;
  }

  return null;
}

function average(values: number[]) {
  const clean = values.filter((item) => Number.isFinite(item));
  if (!clean.length) return 0;
  return clean.reduce((sum, item) => sum + item, 0) / clean.length;
}

function median(values: number[]) {
  const clean = values.filter((item) => Number.isFinite(item)).sort((a, b) => a - b);
  if (!clean.length) return null;

  const middle = Math.floor(clean.length / 2);
  if (clean.length % 2) return clean[middle];

  return (clean[middle - 1] + clean[middle]) / 2;
}

function mode(values: number[]) {
  const clean = values.filter((item) => Number.isFinite(item)).map((item) => Math.round(item));
  if (!clean.length) return null;

  const counts = new Map<number, number>();

  for (const value of clean) {
    counts.set(value, (counts.get(value) || 0) + 1);
  }

  return Array.from(counts.entries()).sort((a, b) => b[1] - a[1] || b[0] - a[0])[0]?.[0] ?? null;
}

function percentLevel(percentage: number) {
  if (percentage >= 80) return "مرتفع";
  if (percentage >= 60) return "جيد";
  if (percentage >= 40) return "متوسط";
  return "منخفض";
}

function buildStudentsFromSummary(summary: GenericRecord): StudentSummary[] {
  const rawStudents = asArray(summary.students);

  return rawStudents
    .map((item) => {
      const row = asRecord(item);
      const name = pickText(row.name, row.fullName, row.studentName, row.student);
      const score = asNumber(row.score) ?? asNumber(row.obtainedScore) ?? null;
      const total = asNumber(row.total) ?? asNumber(row.maxScore) ?? asNumber(row.totalScore) ?? null;

      const percentage =
        asNumber(row.percentage) ??
        asNumber(row.averagePercentage) ??
        (typeof score === "number" &&
        typeof total === "number" &&
        Number.isFinite(score) &&
        Number.isFinite(total) &&
        total > 0
          ? (score / total) * 100
          : null);

      if (!name || typeof percentage !== "number" || !Number.isFinite(percentage)) return null;

      return {
        name,
        percentage,
        score,
        total,
      };
    })
    .filter(Boolean) as StudentSummary[];
}

function buildStudentsFromRows(rows: GenericRecord[]): StudentSummary[] {
  const grouped = new Map<
    string,
    {
      name: string;
      percentages: number[];
      scores: number[];
      totals: number[];
    }
  >();

  for (const row of rows) {
    const name = getRowStudentName(row);
    if (!name) continue;

    const percentage = getRowPercentage(row);
    const score = getRowScore(row);
    const total = getRowTotal(row);

    const current =
      grouped.get(name) ||
      ({
        name,
        percentages: [],
        scores: [],
        totals: [],
      } satisfies {
        name: string;
        percentages: number[];
        scores: number[];
        totals: number[];
      });

    if (typeof percentage === "number" && Number.isFinite(percentage)) current.percentages.push(percentage);
    if (typeof score === "number" && Number.isFinite(score)) current.scores.push(score);
    if (typeof total === "number" && Number.isFinite(total)) current.totals.push(total);

    grouped.set(name, current);
  }

  return Array.from(grouped.values()).map((item) => {
    const score = item.scores.length ? item.scores.reduce((sum, value) => sum + value, 0) : null;
    const total = item.totals.length ? item.totals.reduce((sum, value) => sum + value, 0) : null;

    const percentage =
      item.percentages.length > 0
        ? average(item.percentages)
        : typeof score === "number" &&
          typeof total === "number" &&
          Number.isFinite(score) &&
          Number.isFinite(total) &&
          total > 0
        ? (score / total) * 100
        : 0;

    return {
      name: item.name,
      percentage,
      score,
      total,
    };
  });
}

function buildSubjectSummaries(rows: GenericRecord[]) {
  const grouped = new Map<string, { name: string; percentages: number[]; students: Set<string> }>();

  for (const row of rows) {
    const subject = getRowSubject(row);
    if (!subject) continue;

    const percentage = getRowPercentage(row);
    const studentName = getRowStudentName(row);

    const current =
      grouped.get(subject) ||
      ({
        name: subject,
        percentages: [],
        students: new Set<string>(),
      } satisfies {
        name: string;
        percentages: number[];
        students: Set<string>;
      });

    if (typeof percentage === "number" && Number.isFinite(percentage)) current.percentages.push(percentage);
    if (studentName) current.students.add(studentName);

    grouped.set(subject, current);
  }

  return Array.from(grouped.values())
    .map((item) => ({
      name: item.name,
      averagePercentage: average(item.percentages),
      studentsCount: item.students.size,
    }))
    .sort((a, b) => b.averagePercentage - a.averagePercentage);
}

function joinLimited(items: string[], limit = 2, fallback = "غير متوفر في الملف المرفق") {
  const clean = unique(items).slice(0, limit);
  if (!clean.length) return fallback;
  return clean.join("، ");
}

function prepareReportData(input: AssessmentPdfBuildInput) {
  const analysis = asRecord(input.analysis);
  const summary = asRecord(input.summary);
  const rows = (input.rows || []).map(asRecord);
  const schoolProfile = asRecord(input.schoolProfile);

  const students = buildStudentsFromSummary(summary).length
    ? buildStudentsFromSummary(summary)
    : buildStudentsFromRows(rows);

  const percentages = students
    .map((student) => student.percentage)
    .filter((value) => Number.isFinite(value));

  const totalStudents =
    students.length ||
    asNumber(summary.totalStudents) ||
    asNumber(summary.studentsCount) ||
    asNumber(analysis.studentsCount) ||
    0;

  const totalRows =
    asNumber(summary.rowsCount) ??
    asNumber(summary.totalRows) ??
    asNumber(analysis.rowsCount) ??
    rows.length;

  const averagePercentage =
    asNumber(summary.averagePercentage) ??
    asNumber(summary.avgPercentage) ??
    asNumber(analysis.averagePercentage) ??
    average(percentages);

  const successThreshold = 60;
  const successCount = students.filter((student) => student.percentage >= successThreshold).length;
  const successRate =
    asNumber(summary.successRate) ??
    asNumber(analysis.successRate) ??
    (students.length ? (successCount / students.length) * 100 : 0);

  const highCount = students.filter((student) => student.percentage >= 80).length;
  const goodCount = students.filter((student) => student.percentage >= 60 && student.percentage < 80).length;
  const mediumCount = students.filter((student) => student.percentage >= 40 && student.percentage < 60).length;
  const lowCount = students.filter((student) => student.percentage < 40).length;

  const levelTotal = highCount + goodCount + mediumCount + lowCount;
  const safeTotal = levelTotal || totalStudents || students.length || 0;

  const levels: LevelSummary[] = [
    {
      title: "المستوى المرتفع",
      colorClass: "green",
      count: highCount,
      percentage: safeTotal ? (highCount / safeTotal) * 100 : 0,
      range: "80% فأكثر",
    },
    {
      title: "المستوى الجيد",
      colorClass: "blue",
      count: goodCount,
      percentage: safeTotal ? (goodCount / safeTotal) * 100 : 0,
      range: "60% إلى أقل من 80%",
    },
    {
      title: "المستوى المتوسط",
      colorClass: "turq",
      count: mediumCount,
      percentage: safeTotal ? (mediumCount / safeTotal) * 100 : 0,
      range: "40% إلى أقل من 60%",
    },
    {
      title: "المستوى المنخفض",
      colorClass: "red",
      count: lowCount,
      percentage: safeTotal ? (lowCount / safeTotal) * 100 : 0,
      range: "أقل من 40%",
    },
  ];

  const subjects = buildSubjectSummaries(rows);

  const subjectsFromRows = rows.map(getRowSubject).filter(Boolean);
  const gradesFromRows = rows.map(getRowGrade).filter(Boolean);
  const classroomsFromRows = rows.map(getRowClassroom).filter(Boolean);

  const studentScores = students
    .map((student) => student.score)
    .filter((value): value is number => typeof value === "number" && Number.isFinite(value));

  const studentTotals = students
    .map((student) => student.total)
    .filter((value): value is number => typeof value === "number" && Number.isFinite(value));

  const totalScore =
    asNumber(summary.totalScore) ??
    asNumber(summary.maxScore) ??
    asNumber(analysis.totalScore) ??
    (studentTotals.length ? Math.max(...studentTotals) : null);

  const averageScore =
    asNumber(summary.averageScore) ??
    asNumber(analysis.averageScore) ??
    (typeof totalScore === "number" && totalScore > 0
      ? (averagePercentage / 100) * totalScore
      : studentScores.length
      ? average(studentScores)
      : null);

  const medianValue =
    asNumber(summary.median) ??
    asNumber(summary.medianScore) ??
    (studentScores.length ? median(studentScores) : median(percentages));

  const modeValue =
    asNumber(summary.mode) ??
    asNumber(summary.modeScore) ??
    (studentScores.length ? mode(studentScores) : mode(percentages));

  const highest =
    asNumber(summary.highestScore) ??
    asNumber(summary.maxScoreValue) ??
    (studentScores.length ? Math.max(...studentScores) : percentages.length ? Math.max(...percentages) : null);

  const lowest =
    asNumber(summary.lowestScore) ??
    asNumber(summary.minScoreValue) ??
    (studentScores.length ? Math.min(...studentScores) : percentages.length ? Math.min(...percentages) : null);

  const difficulty = typeof averagePercentage === "number" ? averagePercentage / 100 : null;

  const topLevel = levels.slice().sort((a, b) => b.percentage - a.percentage)[0];
  const lowSubjects = subjects.slice().sort((a, b) => a.averagePercentage - b.averagePercentage);
  const highSubjects = subjects.slice().sort((a, b) => b.averagePercentage - a.averagePercentage);
  const lowStudents = students.slice().sort((a, b) => a.percentage - b.percentage).slice(0, 5);
  const improvementCount = students.filter((student) => student.percentage < 90).length;
  const excellenceCount = highCount;
  const supportCount = mediumCount + lowCount;

  const schoolName =
    pickText(schoolProfile.schoolName, schoolProfile.name, schoolProfile.title, analysis.schoolName) ||
    "غير متوفر في الملف المرفق";

  const principalName =
    pickText(schoolProfile.principalName, schoolProfile.principal, schoolProfile.managerName) ||
    "غير متوفر في الملف المرفق";

  const reportTitle = pickText(analysis.title, analysis.name) || "تقرير تحليل نتائج الطلاب";

  const allSubjects = unique(subjectsFromRows);
  const subjectLabel =
    pickText(analysis.subject, analysis.subjectName) ||
    (allSubjects.length > 1 ? `${allSubjects.length} مواد دراسية` : allSubjects[0]) ||
    "غير متوفر في الملف المرفق";

  const gradeLabel =
    pickText(analysis.grade, analysis.gradeName) || joinLimited(gradesFromRows, 2, "غير متوفر في الملف المرفق");

  const classroomLabel =
    pickText(analysis.classroom, analysis.classroomName) ||
    joinLimited(classroomsFromRows, 2, "غير متوفر في الملف المرفق");

  const termLabel =
    pickText(analysis.term, analysis.termName, analysis.semester, analysis.academicTerm) ||
    "غير متوفر في الملف المرفق";

  const academicYear =
    pickText(analysis.academicYear, analysis.year, schoolProfile.academicYear) ||
    "غير متوفر في الملف المرفق";

  const createdAt = formatDate(analysis.createdAt || analysis.updatedAt || new Date());

  return {
    reportTitle,
    schoolName,
    principalName,
    subjectLabel: normalizeSubjectText(subjectLabel),
    gradeLabel,
    classroomLabel,
    termLabel,
    academicYear,
    createdAt,
    totalStudents: safeTotal,
    totalRows,
    totalScore,
    averageScore,
    medianValue,
    modeValue,
    highest,
    lowest,
    averagePercentage,
    successRate,
    masteryRate: averagePercentage,
    difficulty,
    levels,
    topLevel,
    subjects,
    lowSubjects,
    highSubjects,
    lowStudents,
    improvementCount,
    excellenceCount,
    supportCount,
    successCount,
    lowCount,
    mediumCount,
    highCount,
  };
}

