function metricCard(type: string, tone: "green" | "blue" | "turq" | "red", value: string, label: string) {
  return `
      <div class="metric-card ${tone}">
        <div class="metric-icon">${metricIcon(type)}</div>
        <div class="metric-number">${escapeHtml(value)}</div>
        <div class="metric-label">${escapeHtml(label)}</div>
      </div>`;
}

function infoItem(type: string, label: string, value: string) {
  return `
      <div class="info-item">
        <div class="info-icon">${infoIcon(type)}</div>
        <div>
          <div class="info-label">${escapeHtml(label)}</div>
          <div class="info-value">${escapeHtml(value)}</div>
        </div>
      </div>`;
}

function buildDonutStyle(levels: LevelSummary[]) {
  const high = levels[0]?.percentage || 0;
  const good = levels[1]?.percentage || 0;
  const medium = levels[2]?.percentage || 0;

  const stop1 = high;
  const stop2 = high + good;
  const stop3 = high + good + medium;

  return `conic-gradient(var(--green) 0 ${stop1.toFixed(2)}%, var(--blue) ${stop1.toFixed(
    2
  )}% ${stop2.toFixed(2)}%, var(--turq) ${stop2.toFixed(2)}% ${stop3.toFixed(
    2
  )}%, var(--soft-red) ${stop3.toFixed(2)}% 100%)`;
}

function levelRow(level: LevelSummary) {
  const colorClass =
    level.colorClass === "green"
      ? "level-high"
      : level.colorClass === "blue"
      ? "level-good"
      : level.colorClass === "turq"
      ? "level-mid"
      : "level-low";

  const badgeClass =
    level.colorClass === "green"
      ? "c-green"
      : level.colorClass === "blue"
      ? "c-blue"
      : level.colorClass === "turq"
      ? "c-turq"
      : "c-red";

  return `
              <tr>
                <td class="${colorClass}">${escapeHtml(level.title)}</td>
                <td>${escapeHtml(String(level.count))} طالب/ـة</td>
                <td class="${colorClass}">${escapeHtml(formatPercent(level.percentage, 1))}</td>
                <td><span class="badge ${badgeClass}"></span></td>
              </tr>`;
}

function summaryLine(icon: string, text: string) {
  return `
          <div class="summary-line">
            <div class="summary-icon">${icon}</div>
            <div class="summary-text">${text}</div>
          </div>`;
}

function buildSummaryLines(data: ReturnType<typeof prepareReportData>) {
  const improvementText =
    data.improvementCount > 0
      ? `يوجد <span class="blue">${escapeHtml(String(data.improvementCount))}</span> طالب/ـة دون 90%، وهم الفئة الأنسب للتحسين الدقيق ورفع مستوى الإتقان.`
      : `جميع الطلاب في نطاق أداء مرتفع، ويُوصى بالتركيز على الإثراء والمحافظة على التميز.`;

  const supportText =
    data.supportCount > 0
      ? `تحتاج فئة الدعم المباشر إلى متابعة منظمة، وعددها <span class="red">${escapeHtml(
          String(data.supportCount)
        )}</span> طالب/ـة.`
      : `لا توجد فئة دعم عاجل ظاهرة، ويمكن تحويل الجهد إلى المتابعة الفردية للطلاب الأقل أداءً داخل العينة.`;

  const subjectsText = data.lowSubjects.length
    ? `تظهر أولوية التحسين في: <span class="blue">${escapeHtml(
        data.lowSubjects
          .slice(0, 2)
          .map((item) => item.name)
          .join("، ")
      )}</span>.`
    : `تحتاج قراءة المواد إلى بيانات أكثر تفصيلًا داخل الملف.`;

  return [
    summaryLine(
      metricIcon("average"),
      `بلغ المتوسط العام للطلاب <b>${escapeHtml(
        formatPercent(data.averagePercentage, 1)
      )}</b>، ونسبة النجاح <span class="green">${escapeHtml(
        formatPercent(data.successRate, 1)
      )}</span>.`
    ),
    summaryLine(metricIcon("students"), improvementText),
    summaryLine(metricIcon("target"), `${supportText} ${subjectsText}`),
  ].join("");
}

function buildLowStudentsNote(data: ReturnType<typeof prepareReportData>) {
  if (!data.lowStudents.length) return "غير متوفر في الملف المرفق";

  return data.lowStudents
    .slice(0, 3)
    .map((student) => `${student.name} (${formatPercent(student.percentage, 1)})`)
    .join("، ");
}


function readPublicImageAsDataUri(relativePublicPath: string) {
  try {
    const safePath = relativePublicPath.replace(/^[/\\]+/, "");
    const filePath = path.join(process.cwd(), "public", safePath);

    if (!fs.existsSync(filePath)) {
      return "";
    }

    const ext = path.extname(filePath).toLowerCase();
    const mime =
      ext === ".svg"
        ? "image/svg+xml"
        : ext === ".jpg" || ext === ".jpeg"
          ? "image/jpeg"
          : "image/png";

    return `data:${mime};base64,${fs.readFileSync(filePath).toString("base64")}`;
  } catch {
    return "";
  }
}

function getAssessmentMoeLogoDataUri() {
  try {
    const filePath = join(process.cwd(), "public", "uploads", "school-logos", "MOE.png");

    if (!existsSync(filePath)) {
      return "";
    }

    const ext = extname(filePath).toLowerCase();
    const mime =
      ext === ".jpg" || ext === ".jpeg"
        ? "image/jpeg"
        : ext === ".svg"
          ? "image/svg+xml"
          : "image/png";

    return `data:${mime};base64,${readFileSync(filePath).toString("base64")}`;
  } catch {
    return "";
  }
}
